21	const GROUND_MOUSE_TEXTURE_CHANNELS = 4;
22	const GROUND_MOUSE_TEXTURE_FADE = 0.94;
23	const GROUND_MOUSE_TEXTURE_RADIUS = 0.055;
24	const GROUND_MOUSE_TEXTURE_FALLOFF = 1.85;
25	const GROUND_DEFAULT_RESOLUTION = 1;
26	const GROUND_DEFAULT_POINTER = 0.5;
27	
28	export class Ground
29	  extends SceneObject<GroundTweenProps>
30	  implements GroundRuntimePort
31	{
32	  private _model: THREE.Group | null = null;
33	  private _panelLights: THREE.PointLight[] = [];
34	  private _options: Partial<GroundObjectOptions> = {};
35	  private _shaderMaterials: THREE.ShaderMaterial[] = [];
36	  private _shaderNoiseTexture: THREE.Texture | null = null;
37	  private _shaderNearestNoiseTexture: THREE.Texture | null = null;
38	  private _mouseTexture: THREE.DataTexture | null = null;
39	  private _mouseTextureData: Float32Array | null = null;
40	  private _mouseTextureSize: number = GROUND_SHADER_DEFAULTS.mouseTextureSize;
41	  private _elapsedTime = 0;
42	  private readonly _pointerUv = new THREE.Vector2(
43	    GROUND_DEFAULT_POINTER,
44	    GROUND_DEFAULT_POINTER,
45	  );
46	  private readonly _resolution = new THREE.Vector2(
47	    GROUND_DEFAULT_RESOLUTION,
48	    GROUND_DEFAULT_RESOLUTION,
49	  );
50	  private _pointerActive = false;
51	  private _pointerListenersAttached = false;
52	  private readonly _transitionColor = new THREE.Color();
53	  private readonly _lightColor = new THREE.Color();
54	  private readonly _darkColor = new THREE.Color();
55	  private _runtimeState: GroundRuntimeState = {};
56	  private _resolutionDirty = true;
57	  private _unsubscribeResponsive: (() => void) | null = null;
58	  private _cachedTransitionHex = -1;
59	  private _cachedLightHex = -1;
60	  private _cachedDarkHex = -1;
61	  private readonly _onPointerMove = (event: PointerEvent): void => {
62	    if (typeof window === "undefined") return;
63	    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
64	    const width = Math.max(
65	      GROUND_DEFAULT_RESOLUTION,
66	      responsive.viewportWidth,
67	    );
68	    const height = Math.max(
69	      GROUND_DEFAULT_RESOLUTION,
70	      responsive.viewportHeight,
71	    );
72	    this._pointerUv.set(event.clientX / width, 1 - event.clientY / height);
73	    this._pointerActive = true;
74	  };
75	  private readonly _onPointerLeave = (): void => {
76	    this._pointerActive = false;
77	  };
78	
79	  setOptions(props: Partial<GroundObjectOptions> | undefined): this {
80	    if (props != null) this._options = { ...this._options, ...props };
81	    return this;
82	  }
83	
84	  override getAnimationTarget(): THREE.Object3D | null {
85	    return this.getTimelineRoot();
86	  }
87	
88	  override getTweenApplyMode(): "gsapOnly" {
89	    return "gsapOnly";
90	  }
91	
92	  protected override getOptions(): Record<string, unknown> {
93	    return this._options;
94	  }
95	
96	  protected override applyVisibility(visible: boolean): void {
97	    const root = this.getTimelineRoot();
98	    if (root) root.visible = visible;
99	  }
100	
101	  protected override syncFromOptions(): void {
102	    this._syncTransform();
103	    if (this._model) this._applyMeshShadowSettings(this._model);
104	    this._syncShaderUniforms();
105	  }
