107	  override async runObject(): Promise<void> {
108	    const ctx = this._context;
109	    if (!ctx) return;
110	
111	    const modelUrl = this._options.modelUrl;
112	    if (!modelUrl) {
113	      return;
114	    }
115	
116	    this._unsubscribeResponsive = ResponsiveRuntime.getDefault().subscribe(() => {
117	      this._resolutionDirty = true;
118	    });
119	
120	    try {
121	      await this._prepareShaderResources();
122	      const model = await ctx.loadModel(this.resolveAssetPath(modelUrl));
123	      const group = model as THREE.Group;
124	      this._model = group;
125	      this._applyMeshShadowSettings(group);
126	      this._applyGroundShader(group);
127	      this._attachPanelLights(group);
128	      this.attachToTimelineRoot(group, "groundRoot");
129	      this._syncTransform();
130	      this._syncShaderUniforms();
131	    } catch (error) {
132	    }
133	  }
134	
135	  override runUpdate(delta: number): void {
136	    this._elapsedTime += delta;
137	    this._updateResolution();
138	    this._updateMouseTexture();
139	    this._syncShaderUniforms();
140	  }
141	
142	  override dispose(): void {
143	    this._unsubscribeResponsive?.();
144	    this._unsubscribeResponsive = null;
145	    this._removePointerListeners();
146	    this._disposeShaderResources();
147	    this._disposeGroup(this._model);
148	    this._panelLights.length = 0;
149	    this._model = null;
150	    this._runtimeState = {};
151	    super.dispose();
152	  }
153	
154	  setRuntimeState(state: Partial<GroundRuntimeState>): void {
155	    this._runtimeState = { ...this._runtimeState, ...state };
156	    this._syncShaderUniforms();
157	  }
158	
159	  getRuntimeState(): GroundRuntimeState {
160	    return { ...this._runtimeState };
161	  }
