163	  private _applyMeshShadowSettings(group: THREE.Group): void {
164	    const cast = this._options.meshShadow?.cast;
165	    const receive = this._options.meshShadow?.receive;
166	    group.traverse((obj) => {
167	      if (!(obj instanceof THREE.Mesh)) return;
168	      obj.castShadow = cast ?? false;
169	      obj.receiveShadow = receive ?? false;
170	    });
171	  }
172	
173	  private _attachPanelLights(group: THREE.Group): void {
174	    const specs = this._options.panelLights ?? [];
175	    if (!specs.length) return;
176	
177	    const exactById = new Map(specs.map((spec) => [spec.id, spec as LightSpec]));
178	    const partialSpecs = specs
179	      .map((spec) => {
180	        const raw = (spec as LightSpec & { match?: string | string[] }).match;
181	        const tokens = Array.isArray(raw)
182	          ? raw
183	          : typeof raw === "string"
184	            ? [raw]
185	            : [];
186	        const normalized = tokens
187	          .map((token) => token.trim().toLowerCase())
188	          .filter((token) => token.length > 0);
189	        return { spec: spec as LightSpec, tokens: normalized };
190	      })
191	      .filter((entry) => entry.tokens.length > 0);
192	
193	    group.traverse((obj) => {
194	      if (!(obj instanceof THREE.Mesh)) return;
195	      const mat = obj.material;
196	      const matName =
197	        (Array.isArray(mat) ? mat[0]?.name : (mat as THREE.Material)?.name) ??
198	        "";
199	      const objName = obj.name ?? "";
200	      const names = [objName, matName]
201	        .map((name) => name.trim())
202	        .filter((name) => name.length > 0);
203	      const namesLower = names.map((name) => name.toLowerCase());
204	      const exactKey = names.find((name) => exactById.has(name));
205	      const partial = partialSpecs.find((entry) =>
206	        entry.tokens.some((token) =>
207	          namesLower.some((name) => name.includes(token)),
208	        ),
209	      );
210	      const spec = exactKey ? exactById.get(exactKey)! : partial?.spec;
211	      if (!spec) return;
212	
213	      if (
214	        !Number.isFinite(spec.color as number) ||
215	        !Number.isFinite(spec.intensity as number)
216	      ) {
217	        return;
218	      }
219	
220	      const light = createPointLightFromSpec(
221	        spec,
222	        Number(spec.color),
223	        Number(spec.intensity),
224	      );
225	      const position = spec.position ?? {};
226	      light.position.set(position.x ?? 0, position.y ?? 0, position.z ?? 0);
227	      light.name = `ground:${spec.id}`;
228	      obj.add(light);
229	      this._panelLights.push(light);
230	    });
231	  }
232	
233	  private _syncTransform(): void {
234	    const root = this.getTimelineRoot();
235	    if (!root) return;
236	    Helpers.applyTransform(root, this._options);
237	  }
