239	  private async _prepareShaderResources(): Promise<void> {
240	    this._disposeShaderResources();
241	    if (!this._isShaderEnabled()) return;
242	    const ctx = this._context;
243	    const noiseTextureUrl = this._options.shader?.noiseTextureUrl?.trim();
244	    if (!ctx?.loadTexture || !noiseTextureUrl) return;
245	    const noiseTexture = await ctx.loadTexture(this.resolveAssetPath(noiseTextureUrl));
246	    this._shaderNoiseTexture = noiseTexture;
247	    this._shaderNoiseTexture.wrapS = THREE.RepeatWrapping;
248	    this._shaderNoiseTexture.wrapT = THREE.RepeatWrapping;
249	    this._shaderNoiseTexture.magFilter = THREE.LinearFilter;
250	    this._shaderNoiseTexture.minFilter = THREE.LinearMipmapLinearFilter;
251	    this._shaderNoiseTexture.needsUpdate = true;
252	    ctx.prepareTexture?.(this._shaderNoiseTexture);
253	
254	    this._shaderNearestNoiseTexture = this._shaderNoiseTexture.clone();
255	    this._shaderNearestNoiseTexture.wrapS = THREE.RepeatWrapping;
256	    this._shaderNearestNoiseTexture.wrapT = THREE.RepeatWrapping;
257	    this._shaderNearestNoiseTexture.magFilter = THREE.NearestFilter;
258	    this._shaderNearestNoiseTexture.minFilter = THREE.NearestFilter;
259	    this._shaderNearestNoiseTexture.generateMipmaps = false;
260	    this._shaderNearestNoiseTexture.needsUpdate = true;
261	    ctx.prepareTexture?.(this._shaderNearestNoiseTexture);
262	
263	    this._mouseTextureSize = this._resolveMouseTextureSize();
264	    this._mouseTextureData = new Float32Array(
265	      this._mouseTextureSize *
266	        this._mouseTextureSize *
267	        GROUND_MOUSE_TEXTURE_CHANNELS,
268	    );
269	    this._mouseTexture = new THREE.DataTexture(
270	      this._mouseTextureData,
271	      this._mouseTextureSize,
272	      this._mouseTextureSize,
273	      THREE.RGBAFormat,
274	      THREE.FloatType,
275	    );
276	    this._mouseTexture.wrapS = THREE.ClampToEdgeWrapping;
277	    this._mouseTexture.wrapT = THREE.ClampToEdgeWrapping;
278	    this._mouseTexture.magFilter = THREE.LinearFilter;
279	    this._mouseTexture.minFilter = THREE.LinearFilter;
280	    this._mouseTexture.generateMipmaps = false;
281	    this._mouseTexture.needsUpdate = true;
282	    ctx.prepareTexture?.(this._mouseTexture);
283	    this._installPointerListeners();
284	  }
285	
286	  private _applyGroundShader(group: THREE.Group): void {
287	    this._shaderMaterials = [];
288	    if (!this._isShaderEnabled()) return;
289	    if (!this._shaderNoiseTexture || !this._shaderNearestNoiseTexture || !this._mouseTexture) {
290	      return;
291	    }
292	    const replacedMaterials = new Set<THREE.Material>();
293	    group.traverse((child) => {
294	      if (!(child instanceof THREE.Mesh)) return;
295	      const currentMaterials = Array.isArray(child.material)
296	        ? child.material
297	        : [child.material];
298	      if (currentMaterials.some((m) => m?.userData?.__groundShaderApplied)) {
299	        return;
300	      }
301	      for (const material of currentMaterials) replacedMaterials.add(material);
302	      child.material = this._createShaderMaterialSet(child.material);
303	    });
304	    for (const material of replacedMaterials) material.dispose();
305	  }
306	
307	  private _createShaderMaterialSet(
308	    material: THREE.Material | THREE.Material[],
309	  ): THREE.Material | THREE.Material[] {
310	    if (Array.isArray(material)) {
311	      return material.map((entry) => this._createShaderMaterial(entry));
312	    }
313	    return this._createShaderMaterial(material);
314	  }
315	
316	  private _createShaderMaterial(material: THREE.Material): THREE.Material {
317	    const nextMaterial = new THREE.ShaderMaterial({
318	      uniforms: {
319	        uGroundResolution: { value: this._resolution.clone() },
320	        uGroundTime: { value: this._elapsedTime },
321	        uGroundPage: { value: this._readShaderRuntimeValue("page") },
322	        uGroundScrollProgress: {
323	          value: this._readShaderRuntimeValue("scrollProgress"),
324	        },
325	        uGroundTransition: {
326	          value: this._readShaderRuntimeValue("transition"),
327	        },
328	        uGroundTransitionDirection: {
329	          value: this._readShaderRuntimeValue("transitionDirection"),
330	        },
331	        uGroundChapter: {
332	          value: this._readShaderRuntimeValue("chapter"),
333	        },
334	        uGroundTransitionColor: {
335	          value: this._transitionColor.clone(),
336	        },
337	        uGroundLightColor: {
338	          value: this._lightColor.clone(),
339	        },
340	        uGroundDarkColor: {
341	          value: this._darkColor.clone(),
342	        },
343	        tGroundNoise: { value: this._shaderNoiseTexture },
344	        tGroundNearestNoise: {
345	          value: this._shaderNearestNoiseTexture,
346	        },
347	        tGroundMouse: { value: this._mouseTexture },
348	      },
349	      vertexShader: groundSurfaceVertexShader,
350	      fragmentShader: groundSurfaceFragmentShader,
351	      transparent: false,
352	      depthTest: true,
353	      depthWrite: true,
354	      side: material.side,
355	    });
356	    nextMaterial.userData.__groundShaderApplied = true;
357	    this._shaderMaterials.push(nextMaterial);
358	    return nextMaterial;
359	  }
360	
361	  private _syncShaderUniforms(): void {
362	    if (this._shaderMaterials.length === 0) return;
363	    this._updateResolution();
364	    this._resolveShaderColors();
365	    const page = this._readShaderRuntimeValue("page");
366	    const scrollProgress = this._readShaderRuntimeValue("scrollProgress");
367	    const transition = this._readShaderRuntimeValue("transition");
368	    const transitionDirection = this._readShaderRuntimeValue(
369	      "transitionDirection",
370	    );
371	    const chapter = this._readShaderRuntimeValue("chapter");
372	    for (const material of this._shaderMaterials) {
373	      material.uniforms.uGroundResolution.value.copy(this._resolution);
374	      material.uniforms.uGroundTime.value = this._elapsedTime;
375	      material.uniforms.uGroundPage.value = page;
376	      material.uniforms.uGroundScrollProgress.value = scrollProgress;
377	      material.uniforms.uGroundTransition.value = transition;
378	      material.uniforms.uGroundTransitionDirection.value = transitionDirection;
379	      material.uniforms.uGroundChapter.value = chapter;
380	      material.uniforms.uGroundTransitionColor.value.copy(
381	        this._transitionColor,
382	      );
383	      material.uniforms.uGroundLightColor.value.copy(this._lightColor);
384	      material.uniforms.uGroundDarkColor.value.copy(this._darkColor);
385	    }
386	  }
387	
388	  private _readShaderRuntimeValue(
389	    key: "page" | "scrollProgress" | "transition" | "transitionDirection" | "chapter",
390	  ): number {
391	    const runtimeValue = this._runtimeState[key];
392	    if (typeof runtimeValue === "number" && Number.isFinite(runtimeValue)) {
393	      return runtimeValue;
394	    }
395	    const runtime = this._options.shader?.runtime;
396	    const fallback = GROUND_SHADER_DEFAULTS.runtime[key];
397	    const value = runtime?.[key];
398	    if (typeof value === "number" && Number.isFinite(value)) return value;
399	    return fallback;
400	  }
401	
402	  private _resolveMouseTextureSize(): number {
403	    const raw = this._options.shader?.mouseTextureSize;
404	    if (!Number.isFinite(raw)) return GROUND_SHADER_DEFAULTS.mouseTextureSize;
405	    return Math.max(8, Math.round(raw as number));
406	  }
407	
408	  private _resolveShaderColors(): void {
409	    const colors = this._options.shader?.colors;
410	    const tHex = colors?.transition ?? GROUND_SHADER_DEFAULTS.colors.transition;
411	    const lHex = colors?.light ?? GROUND_SHADER_DEFAULTS.colors.light;
412	    const dHex = colors?.dark ?? GROUND_SHADER_DEFAULTS.colors.dark;
413	    if (tHex !== this._cachedTransitionHex) { this._cachedTransitionHex = tHex; this._transitionColor.setHex(tHex); }
414	    if (lHex !== this._cachedLightHex) { this._cachedLightHex = lHex; this._lightColor.setHex(lHex); }
415	    if (dHex !== this._cachedDarkHex) { this._cachedDarkHex = dHex; this._darkColor.setHex(dHex); }
416	  }
417	
418	  private _updateResolution(): void {
419	    if (!this._resolutionDirty) return;
420	    this._resolutionDirty = false;
421	    if (typeof window === "undefined") {
422	      this._resolution.set(GROUND_DEFAULT_RESOLUTION, GROUND_DEFAULT_RESOLUTION);
423	      return;
424	    }
425	    const snapshot = ResponsiveRuntime.getDefault().getSnapshot();
426	    this._resolution.set(
427	      Math.max(GROUND_DEFAULT_RESOLUTION, snapshot.viewportWidth),
428	      Math.max(GROUND_DEFAULT_RESOLUTION, snapshot.viewportHeight),
429	    );
430	  }
431	
432	  private _updateMouseTexture(): void {
433	    const mouseTexture = this._mouseTexture;
434	    const mouseTextureData = this._mouseTextureData;
435	    if (!mouseTexture || !mouseTextureData) return;
436	    for (
437	      let index = 0;
438	      index < mouseTextureData.length;
439	      index += GROUND_MOUSE_TEXTURE_CHANNELS
440	    ) {
441	      mouseTextureData[index] *= GROUND_MOUSE_TEXTURE_FADE;
442	      mouseTextureData[index + 1] *= GROUND_MOUSE_TEXTURE_FADE;
443	      mouseTextureData[index + 2] *= GROUND_MOUSE_TEXTURE_FADE;
444	      mouseTextureData[index + 3] = 1;
445	    }
446	    if (!this._pointerActive) {
447	      mouseTexture.needsUpdate = true;
448	      return;
449	    }
450	
451	    const size = this._mouseTextureSize;
452	    const pointerX = this._pointerUv.x * (size - 1);
453	    const pointerY = this._pointerUv.y * (size - 1);
454	    const radius = Math.max(1, Math.round(size * GROUND_MOUSE_TEXTURE_RADIUS));
455	
456	    for (let y = -radius; y <= radius; y += 1) {
457	      const pixelY = Math.round(pointerY + y);
458	      if (pixelY < 0 || pixelY >= size) continue;
459	      for (let x = -radius; x <= radius; x += 1) {
460	        const pixelX = Math.round(pointerX + x);
461	        if (pixelX < 0 || pixelX >= size) continue;
462	        const distance = Math.sqrt(x * x + y * y) / radius;
463	        if (distance > 1) continue;
464	        const strength = Math.pow(1 - distance, GROUND_MOUSE_TEXTURE_FALLOFF);
465	        const pixelIndex =
466	          (pixelY * size + pixelX) * GROUND_MOUSE_TEXTURE_CHANNELS;
467	        mouseTextureData[pixelIndex] = Math.max(
468	          mouseTextureData[pixelIndex],
469	          strength,
470	        );
471	        mouseTextureData[pixelIndex + 1] = Math.max(
472	          mouseTextureData[pixelIndex + 1],
473	          strength * 0.6,
474	        );
475	        mouseTextureData[pixelIndex + 2] = Math.max(
476	          mouseTextureData[pixelIndex + 2],
477	          strength * 0.85,
478	        );
479	      }
480	    }
481	
482	    mouseTexture.needsUpdate = true;
483	  }
484	
485	  private _installPointerListeners(): void {
486	    if (this._pointerListenersAttached || typeof window === "undefined") return;
487	    window.addEventListener("pointermove", this._onPointerMove, { passive: true });
488	    window.addEventListener("pointerleave", this._onPointerLeave);
489	    this._pointerListenersAttached = true;
490	  }
491	
492	  private _removePointerListeners(): void {
493	    if (!this._pointerListenersAttached || typeof window === "undefined") return;
494	    window.removeEventListener("pointermove", this._onPointerMove);
495	    window.removeEventListener("pointerleave", this._onPointerLeave);
496	    this._pointerListenersAttached = false;
497	  }
498	
499	  private _disposeShaderResources(): void {
500	    this._shaderMaterials = [];
501	    this._shaderNoiseTexture?.dispose();
502	    this._shaderNearestNoiseTexture?.dispose();
503	    this._mouseTexture?.dispose();
504	    this._shaderNoiseTexture = null;
505	    this._shaderNearestNoiseTexture = null;
506	    this._mouseTexture = null;
507	    this._mouseTextureData = null;
508	    this._mouseTextureSize = GROUND_SHADER_DEFAULTS.mouseTextureSize;
509	  }
510	
511	  private _isShaderEnabled(): boolean {
512	    return this._options.shader?.enabled ?? GROUND_SHADER_DEFAULTS.enabled;
513	  }
514	
515	  private _disposeGroup(group: THREE.Group | null): void {
516	    if (!group) return;
517	    group.traverse((child) => {
518	      if (!(child as THREE.Mesh).isMesh) return;
519	      const mesh = child as THREE.Mesh;
520	      mesh.geometry?.dispose();
521	      const materials = Array.isArray(mesh.material)
522	        ? mesh.material
523	        : [mesh.material];
524	      for (const material of materials) {
525	        material?.dispose?.();
526	      }
527	    });
528	  }
529	}
