### 5. **Proof-Canvas를 Earth 패턴으로 개선하는 방안**

#### 현재 문제:
```typescript
// 현재 (렉 발생)
init() {
  const textures = await Promise.all([...]);  // 병렬 로드
  textures.forEach((texture, i) => {
    this._addCard(group, i, textures.length, texture, radius, sharedGeo);
    // 각 반복마다 Material 생성 → shader 컴파일 지연
  });
}
```

#### 개선 전략:
1. **Material을 init() 완료 후 생성**: RAF 첫 프레임 전에 완료
2. **Shared Material 사용**: 텍스처만 교체하고 Material 재사용
3. **Shader precompile**: init() 완료 후 명시적으로 `renderer.compile()`

```typescript
// 개선안 1: Material 미리 생성
async init(canvas: HTMLCanvasElement): Promise<void> {
  // ... 라인 154-227: Scene/Camera/Lights/Textures 준비

  if (items.length > 0) {
    const radius = computeRadius(textures.length);
    const sharedGeo = createCurvedCardGeometry(CARD_WIDTH, CARD_HEIGHT, radius);

    // Shared Material 생성 (한 번만)
    const sharedMat = createCardMaterial(null, 0xffffff);

    // Card 추가 (Material 재사용)
    textures.forEach((texture, i) => {
      this._addCardWithSharedMaterial(group, i, textures.length, texture, radius, sharedGeo, sharedMat);
    });

    // Shader precompile
    if (this._renderer && this._scene) {
      this._renderer.compile(this._scene, this._camera!);
    }
  }

  // RAF 시작
  this._observeVisibility();
}

private _addCardWithSharedMaterial(
  group: THREE.Group,
  index: number,
  total: number,
  texture: THREE.Texture | null,
  radius: number,
  sharedGeo: THREE.BufferGeometry,
  sharedMat: THREE.MeshBasicMaterial,
): void {
  // Material 생성 제거, mesh만 생성
  const mesh = new THREE.Mesh(sharedGeo, sharedMat);
  // ... 위치/회전 설정
  group.add(mesh);
}
```

